import math

candidates = [
    {"id": "C1_Full_Teacher",    "gmv_lift": 0.026,  "recall": 0.925, "p99_ms": 78.0, "gpu_k": 52.0},
    {"id": "C2_Tiny_Student",    "gmv_lift": 0.019,  "recall": 0.830, "p99_ms": 8.0,  "gpu_k": 4.0},
    {"id": "C3_Strict_Thresh",   "gmv_lift": -0.014, "recall": 0.902, "p99_ms": 8.0,  "gpu_k": 4.0},
    {"id": "C4_Dominated_Old",   "gmv_lift": 0.015,  "recall": 0.890, "p99_ms": 45.0, "gpu_k": 25.0},
    {"id": "C5_Entropy_Cascade", "gmv_lift": 0.023,  "recall": 0.912, "p99_ms": 34.0, "gpu_k": 17.5},
]

def dominates(a, b):
    # বেশি ভালো: gmv_lift, recall | কম ভালো: p99_ms, gpu_k
    no_worse = (
        a["gmv_lift"] >= b["gmv_lift"]
        and a["recall"] >= b["recall"]
        and a["p99_ms"] <= b["p99_ms"]
        and a["gpu_k"] <= b["gpu_k"]
    )
    strictly_better = (
        a["gmv_lift"] > b["gmv_lift"]
        or a["recall"] > b["recall"]
        or a["p99_ms"] < b["p99_ms"]
        or a["gpu_k"] < b["gpu_k"]
    )
    return no_worse and strictly_better

def binary_entropy(p):
    if p <= 0.0 or p >= 1.0:
        return 0.0
    return -(p * math.log2(p) + (1.0 - p) * math.log2(1.0 - p))

# ১) Pareto Frontier বের করা (স্পষ্ট for লুপে)
pareto = []
for cand in candidates:
    is_dominated = False
    for other in candidates:
        if other["id"] != cand["id"] and dominates(other, cand):
            is_dominated = True
            break
    if not is_dominated:
        pareto.append(cand)

# ২) তিনটি টিমের হার্ড Guardrail শর্ত একসাথে পূরণ করে এমন সমাধান খোঁজা
feasible = []
for c in pareto:
    if c["gmv_lift"] > 0.0 and c["recall"] >= 0.90 and c["p99_ms"] <= 40.0 and c["gpu_k"] <= 22.0:
        feasible.append(c)

best_choice = feasible[0]
for c in feasible:
    if c["gmv_lift"] > best_choice["gmv_lift"]:
        best_choice = c

pareto_ids = []
for c in pareto:
    pareto_ids.append(c["id"])

assert "C4_Dominated_Old" not in pareto_ids
assert len(feasible) == 1 and best_choice["id"] == "C5_Entropy_Cascade"

# ৩) Entropy Cascade রাউটিং উদাহরণ (H(p) >= 0.70 হলেই কেবল Teacher-এ পাঠাও!)
sample_probs = [0.02, 0.97, 0.48, 0.05, 0.52, 0.99]
routed_to_teacher = 0
for p in sample_probs:
    if binary_entropy(p) >= 0.70:
        routed_to_teacher += 1

print("Pareto Frontier:", pareto_ids)
print(f"Aligned Winner: {best_choice['id']} (GMV=+{best_choice['gmv_lift']:.1%}, Recall={best_choice['recall']:.1%}, p99={best_choice['p99_ms']}ms, GPU=${best_choice['gpu_k']}K)")
print(f"Entropy Cascade Routed to Teacher: {routed_to_teacher}/{len(sample_probs)} uncertain items")
